/** Public manual illustrations use staged, non-personal application data. */
export interface ManualGuideStep {
  title: string;
  instruction: string;
  image: string;
  alt: string;
  width: number;
  height: number;
}

export interface ManualGuide {
  title: string;
  summary: string;
  /** A short, reader-facing boundary, e.g. a staged editorial reading. */
  note?: string;
  steps: ManualGuideStep[];
}

export type ManualGuides = Record<string, ManualGuide>;
import { chromium, expect } from "/home/diogenes/Projects/twyne/node_modules/@playwright/test/index.mjs";
import { mkdir, writeFile } from "node:fs/promises";

const directory = "/home/diogenes/Projects/twyne/artifacts/qa-recordings/2026-09-30/house-walkthrough";
await mkdir(directory, { recursive: true });
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({
  viewport: { width: 1440, height: 900 },
  recordVideo: { dir: directory, size: { width: 1440, height: 900 } },
});
const page = await context.newPage();
const errors = [];
page.on("pageerror", (error) => errors.push(error.message));
let result;
try {
  await page.route("**/__house-walkthrough-seed", (route) => route.fulfill({
    contentType: "text/html", body: "<!doctype html><title>House fixture</title>",
  }));
  await page.goto("http://127.0.0.1:5180/__house-walkthrough-seed");
  await page.evaluate(async () => {
    const idb = await import("/src/utils/idb.ts");
    const house = await import("/src/utils/house-store.ts");
    const now = Date.now();
    await idb.saveFoliosToIdb([
      { id: "walk-salt", name: "Salt Roads", type: "draft", createdAt: now, updatedAt: now },
      { id: "walk-coast", name: "The Coast in Winter", type: "draft", createdAt: now, updatedAt: now },
    ]);
    await idb.saveActiveFolioIdToIdb("walk-salt");
    await idb.saveFolioContentToIdb("walk-salt", "<p>The traders left before dawn. By the fourth day, the road forgot the sea entirely and turned inland.</p>");
    await idb.saveBriefToIdb("walk-salt", {
      answers: { workingTitle: "Salt Roads", format: "Travel essay", audience: "", goal: "", tone: "", constraints: "", successSignal: "Leave the reader with a place they can picture." },
      attachments: [], completedAt: now, updatedAt: now,
    });
    await house.setHouseName("Éditions du Passage");
    await house.setHouseField("goal", "Make familiar places strange again.");
    await house.setHouseField("audience", "Curious readers who travel through stories.");
    await house.setHouseField("tone", "Attentive, concrete, generous.");
    const state = await house.createCollection("Journeys & Returns", ["walk-salt"]);
    const collection = state.collections[0];
    await house.updateCollection(collection.id, { description: "Essays on roads, memory, and finding a way home.", field: { name: "tone", value: "A close eye for the landscape; a quiet sense of wonder." } });
    await house.upsertCharterItem({ scope: "house", ownerRef: "house", text: "Ground every claim in a concrete scene.", severity: "must", kind: "style" });
  });
  await page.goto("http://127.0.0.1:5180/house/?folio=walk-salt");
  await expect(page.locator(".house-tree")).toBeVisible();
  await expect(page.locator(".house-folder", { hasText: "Salt Roads" })).toHaveAttribute("aria-current", "true");
  await expect(page.locator(".house-sheet")).toContainText("Make familiar places strange again.");
  await page.screenshot({ path: `${directory}/folio-context.png` });
  await page.waitForTimeout(3000);
  await page.locator(".house-node--collection", { hasText: "Journeys & Returns" }).click();
  await expect(page.getByRole("textbox", { name: "Collection name" })).toHaveValue("Journeys & Returns");
  await page.screenshot({ path: `${directory}/collection.png` });
  await page.waitForTimeout(3000);
  await page.locator(".house-node--house").click();
  await expect(page.getByRole("textbox", { name: "Aim", exact: true })).toHaveValue("Make familiar places strange again.");
  await page.screenshot({ path: `${directory}/house.png` });
  await page.waitForTimeout(3000);
  await page.getByRole("button", { name: "The register" }).click();
  await expect(page.locator(".house-register")).toContainText("Journeys & Returns");
  await page.screenshot({ path: `${directory}/register.png` });
  await page.waitForTimeout(3000);
  await page.getByRole("button", { name: "Engine room", exact: true }).click();
  await expect(page.locator(".house-engine")).toBeVisible();
  await page.screenshot({ path: `${directory}/engine.png` });
  await page.waitForTimeout(3000);
  await page.getByRole("button", { name: "The cabinet", exact: true }).click();
  await page.locator(".house-folder", { hasText: "Salt Roads" }).click();
  await page.getByText("What the models read", { exact: true }).scrollIntoViewIfNeeded();
  await page.screenshot({ path: `${directory}/model-context.png` });
  await page.waitForTimeout(3000);
  expect(errors).toEqual([]);
  result = { passed: true, boundary: "Actual local House UI with synthetic folios/context; no authenticated cloud sync or generated Jev decisions.", assertions: "folio inheritance; collection; House defaults; ledger; diagnostics; model-context inspection; no page errors" };
} catch (error) {
  result = { passed: false, error: String(error), pageErrors: errors };
  process.exitCode = 1;
  await page.screenshot({ path: `${directory}/failure.png` });
} finally {
  const video = page.video();
  await context.close();
  result.video = await video.path();
  await browser.close();
  await writeFile(`${directory}/result.json`, JSON.stringify(result, null, 2));
  console.log(JSON.stringify(result, null, 2));
}
import { expect, test } from "@playwright/test";

test("margin conversations preserve replies, own one surface and adapt to mobile", async ({
  page,
}) => {
  await page.setViewportSize({ width: 1600, height: 1000 });
  const errors: string[] = [];
  page.on("pageerror", (error) => errors.push(error.message));
  await page.route("**/__flow-seed", (route) =>
    route.fulfill({
      contentType: "text/html",
      body: "<!doctype html><title>Seed</title>",
    }),
  );
  await page.goto("/__flow-seed");
  await page.evaluate(async () => {
    const idbPath = "/src/utils/idb.ts";
    const commentsPath = "/src/utils/user-comments.ts";
    const idb = await import(/* @vite-ignore */ idbPath);
    const uc = await import(/* @vite-ignore */ commentsPath);
    const now = Date.now();
    const id = "f-margin";
    await idb.saveFoliosToIdb([
      { id, name: "Salt Roads", type: "draft", createdAt: now, updatedAt: now },
    ]);
    await idb.saveActiveFolioIdToIdb(id);
    const paras = Array.from(
      { length: 6 },
      (_, i) =>
        `<p>Paragraph ${i + 1}: the salt caravans left before dawn, and the road bent with the coast for a week of walking.</p>`,
    );
    paras[1] = `<p>The traders <span data-persona-note-id="n1" data-persona-note-author="Marguerite" data-persona-note-color="#b0413e" data-persona-note-label="Pacing" data-persona-note-note="This sentence carries three ideas; let the second breathe." data-persona-note-quote="weighed their loads by the handful">weighed their loads by the handful</span> and argued about the weather.</p>`;
    paras[4] = `<p>At the ford <span data-suggestion-id="s1" data-suggestion-author="Marguerite" data-suggestion-color="#b0413e" data-suggestion-replacement="the mules refused the water" data-suggestion-rationale="Concrete beats abstract here." data-suggestion-versionId="v1">progress slowed considerably</span> for a day.</p>`;
    paras[3] = `<p>By the fourth day <span class="twyne-comment-mark" data-comment-id="c1" data-comment-author="You">the road forgot the sea entirely</span> and turned inland.</p>`;
    await idb.saveFolioContentToIdb(id, paras.join(""));
    await uc.saveUserComments([
      {
        id: "c1",
        folioId: id,
        text: "Is this literally true? Check the map.",
        author: "You",
        anchor: "the road forgot the sea entirely",
        resolved: false,
        createdAt: now,
        updatedAt: now,
        replies: [],
      },
      ...[0, 2, 5].map((i) => ({
        id: `waiting-${i}`,
        folioId: id,
        text: `A margin thought about paragraph ${i + 1}.`,
        author: "Editor",
        anchor: `Paragraph ${i + 1}: the salt caravans left before dawn`,
        resolved: false,
        createdAt: now,
        updatedAt: now,
        replies: [],
      })),
    ]);
    await idb.saveMetaToIdb("flow-reading-enabled", true);
  });

  await page.goto("/editor/");
  const note = page
    .locator('.twyne-mark-anchor[data-anchor-kind="note"]')
    .first();
  const comment = page
    .locator('.twyne-mark-anchor[data-anchor-kind="comment"]')
    .first();
  const suggestion = page
    .locator('.twyne-mark-anchor[data-anchor-kind="suggestion"]')
    .first();
  await expect(page.locator(".flow-column--room")).toBeVisible();
  // Reading the margin only changes its layout. It must never masquerade
  // as an edit (or invalidate a live review waiting for the saved draft).
  await page.evaluate(() => {
    const counts = { content: 0, layout: 0 };
    Object.assign(window, { marginEvents: counts });
    window.addEventListener("twyne:content", () => counts.content++);
    window.addEventListener("twyne:flow-layout", () => counts.layout++);
  });
  const card = page.locator(".flow-card").first();
  await card.hover();
  await card.locator(".flow-card__body").focus();
  const more = page.getByRole("button", { name: /more in the margin/ });
  await expect(more).toBeVisible();
  await more.click();
  await expect(
    page.getByRole("button", { name: "Fewer", exact: true }),
  ).toBeVisible();
  await expect
    .poll(() =>
      page.evaluate(
        () =>
          (window as unknown as { marginEvents: { layout: number } })
            .marginEvents.layout,
      ),
    )
    .toBeGreaterThanOrEqual(3);
  expect(
    await page.evaluate(
      () =>
        (window as unknown as { marginEvents: { content: number } })
          .marginEvents.content,
    ),
  ).toBe(0);
  expect(errors).toEqual([]);
  await note.click();
  const noteDraft = page.getByRole("textbox", { name: "Reply to Marguerite" });
  await noteDraft.fill("A persona reply in progress");
  await comment.click();
  const writerDraft = page.getByRole("textbox", {
    name: "Reply as the writer",
  });
  await writerDraft.fill("A writer reply in progress");
  await note.click();
  await expect(noteDraft).toHaveValue("A persona reply in progress");
  await expect(page.locator(".manuscript-comment-card")).toHaveCount(1);
  await comment.click();
  await expect(writerDraft).toHaveValue("A writer reply in progress");
  await page
    .locator(".manuscript-comment-card")
    .getByRole("button", { name: "Reply", exact: true })
    .click();
  await expect(writerDraft).toHaveValue("");
  await expect(page.locator(".manuscript-comment-card")).toContainText(
    "A writer reply in progress",
  );
  await page
    .locator(".manuscript-comment-card")
    .getByRole("button", { name: "Resolve", exact: true })
    .click();
  await expect(
    page
      .locator(".manuscript-comment-card")
      .getByRole("button", { name: "Reopen", exact: true }),
  ).toBeVisible();
  await suggestion.click();
  await expect(page.locator(".suggestion-card")).toHaveAttribute(
    "data-margin-item",
    "suggestion:s1",
  );
  await expect(page.locator(".manuscript-comment-card")).toHaveCount(1);
  await page.setViewportSize({ width: 390, height: 844 });
  await expect
    .poll(async () => {
      const box = await page.locator(".suggestion-card").boundingBox();
      return (
        !!box &&
        box.x >= 0 &&
        box.x + box.width <= 390 &&
        box.y + box.height <= 844
      );
    })
    .toBe(true);
  await expect(page.locator(".flow-dock")).not.toBeVisible();
  await page.keyboard.press("Escape");
  await expect(page.locator(".manuscript-comment-card")).toHaveCount(0);
  expect(errors).toEqual([]);
});

