  await page
    .locator(".manuscript-comment-card")
    .getByRole("button", { name: "Resolve", exact: true })
    .click();
  await expect(
    page
      .locator(".manuscript-comment-card")
      .getByRole("button", { name: "Reopen", exact: true }),
  ).toBeVisible();
  await suggestion.click();
  await expect(page.locator(".suggestion-card")).toHaveAttribute(
    "data-margin-item",
