import { expect, test, type Page } from "@playwright/test";

/**
 * The dossier used to "file" and then vanish: the brief carried Qwik store
 * Proxies into IndexedDB, structured clone rejected them, and the IDB helper
 * swallowed the DataCloneError. This walks a guest through filing and then
 * refining a dossier and reads the stored record back each time.
 */

const ANSWERS = [
  "Libraries as Civic Infrastructure",
  "Essay",
  "Municipal leaders deciding next year's library budget",
  "Show that library funding is practical civic infrastructure",
  "Calm, evidence-led, and direct",
  "Avoid nostalgia and tie every claim to observable public value",
  "A reader can name three measurable outcomes worth funding",
];

async function storedWorkingTitles(page: Page): Promise<string[]> {
  return page.evaluate(
    () =>
      new Promise<string[]>((resolve, reject) => {
        const open = indexedDB.open("twyne");
        open.onerror = () => reject(open.error);
        open.onsuccess = () => {
          const req = open.result
            .transaction("brief")
            .objectStore("brief")
            .getAll();
          req.onerror = () => reject(req.error);
          req.onsuccess = () =>
            resolve(
              (
                req.result as Array<{
                  brief: { answers: { workingTitle: string } };
                }>
              ).map((record) => record.brief.answers.workingTitle),
            );
        };
      }),
  );
}

/** Step past the optional folios (probes, material, references) and file. */
async function sendToPress(page: Page): Promise<void> {
  const press = page.getByRole("button", { name: /send to press/i });
  const next = page.getByRole("button", { name: "Next", exact: true });
  await expect(async () => {
    if (await next.isVisible()) await next.click();
    await expect(press).toBeVisible({ timeout: 1000 });
  }).toPass({ timeout: 20_000 });
  await press.click();
}

test("a filed and refined dossier survives into the editor", async ({
  page,
}) => {
  await page.goto("/onboarding/");
  await page
    .getByRole("button", { name: /just check things out/i })
    .first()
    .click();
  await page.getByRole("button", { name: "Begin" }).click();
  await expect(page).toHaveURL(/\/dossier\/create\//);

  for (const answer of ANSWERS) {
    await page
      .locator('input:not([type="file"]), textarea')
      .filter({ visible: true })
      .first()
      .fill(answer);
    await page.getByRole("button", { name: "Next", exact: true }).click();
  }
  await sendToPress(page);
  await expect(page.getByText("The dossier is filed")).toBeVisible();
  await expect.poll(() => storedWorkingTitles(page)).toEqual([ANSWERS[0]]);

  await page.getByRole("button", { name: /continue to the editor/i }).click();
  await expect(page).toHaveURL(/\/editor\//);
  const refine = page.getByRole("button", { name: "Refine the dossier" });
  await expect(refine).toBeVisible();

  await refine.click();
  await expect(page).toHaveURL(/\/dossier\/refine\//);
  const title = page
    .locator('input:not([type="file"]), textarea')
    .filter({ visible: true })
    .first();
  await expect(title).toHaveValue(ANSWERS[0]);
  await title.fill("Libraries, Refined");
  await sendToPress(page);

  await expect(page).toHaveURL(/\/editor\//);
  await expect
    .poll(() => storedWorkingTitles(page))
    .toEqual(["Libraries, Refined"]);
  await expect(
    page.getByRole("button", { name: "Refine the dossier" }),
  ).toBeVisible();
});

test("a new folio's name becomes its dossier's working title", async ({
  page,
}) => {
  await page.goto("/onboarding/");
  await page
    .getByRole("button", { name: /just check things out/i })
    .first()
    .click();
  await page.getByRole("button", { name: "Begin" }).click();
  for (const answer of ANSWERS) {
    await page
      .locator('input:not([type="file"]), textarea')
      .filter({ visible: true })
      .first()
      .fill(answer);
    await page.getByRole("button", { name: "Next", exact: true }).click();
  }
  await sendToPress(page);
  await page.getByRole("button", { name: /continue to the editor/i }).click();
  await expect(page).toHaveURL(/\/editor\//);

  await page.getByRole("button", { name: "Toggle the drawer sidebar" }).click();
  await page.getByRole("button", { name: /new folio/i }).click();
  await page.getByPlaceholder("Folio name").fill("Harbour Notes");
  await page.getByRole("button", { name: "Create", exact: true }).click();

  await expect(page).toHaveURL(/\/dossier\/create\/\?folio=/);
  const title = page
    .locator('input:not([type="file"]), textarea')
    .filter({ visible: true })
    .first();
  await expect(title).toHaveValue("Harbour Notes");
  await sendToPress(page);

  await expect
    .poll(async () => (await storedWorkingTitles(page)).sort())
    .toEqual([ANSWERS[0], "Harbour Notes"].sort());
});
import { $, component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import { Link } from "@qwik.dev/router";
import { loadMetaFromIdb, saveMetaToIdb } from "../../utils/idb";
import {
  COVER_LOOKUP_SETTING_KEY,
  FLOW_SETTING_EVENT,
  FLOW_SETTING_KEY,
  IN_FLOW_SETTING_EVENT,
  IN_FLOW_SETTING_KEY,
} from "../../utils/in-flow-events";

type Setting = "enabled" | "tools" | "flow" | "covers";

/** Where each switch is stored, and the event that tells its readers. */
const SETTINGS: Record<Setting, { key: string; event: string }> = {
  enabled: { key: "live-review-enabled", event: "twyne:live-review-setting" },
  tools: { key: IN_FLOW_SETTING_KEY, event: IN_FLOW_SETTING_EVENT },
  flow: { key: FLOW_SETTING_KEY, event: FLOW_SETTING_EVENT },
  covers: { key: COVER_LOOKUP_SETTING_KEY, event: FLOW_SETTING_EVENT },
};

const LABELS: Record<Setting, string> = {
  enabled: "Automatic review",
  tools: "Margin tools",
  flow: "Automatic focus",
  covers: "Cover lookups",
};

const TITLES: Record<Setting, string> = {
  enabled: "Review saved writing automatically. Switch off to pause.",
  tools: "Show small tools beside passages that may need attention.",
  flow: "Read the rhythm of your typing: go quiet and into focus while you're writing steadily, and bring help in when you stall.",
  covers:
    "Look up the books and records your draft names for a cover card. Only the title leaves this device.",
};

export const ReviewControls = component$(() => {
  const state = useStore({
    enabled: true,
    tools: true,
    flow: true,
    covers: true,
    ready: false,
    saving: false,
    error: "",
  });
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(
    ({ cleanup }) => {
      let disposed = false;
      const update = async () => {
        const [enabled, tools, flow, covers] = await Promise.all(
          (["enabled", "tools", "flow", "covers"] as const).map((setting) =>
            loadMetaFromIdb<boolean>(SETTINGS[setting].key),
          ),
        );
        if (disposed) return;
        state.enabled = enabled !== false;
        state.tools = tools !== false;
        state.flow = flow !== false;
        state.covers = covers !== false;
        state.ready = true;
      };
      void update();
      window.addEventListener("twyne:live-review-setting", update);
      window.addEventListener(IN_FLOW_SETTING_EVENT, update);
      window.addEventListener(FLOW_SETTING_EVENT, update);
      cleanup(() => {
        disposed = true;
        window.removeEventListener("twyne:live-review-setting", update);
        window.removeEventListener(IN_FLOW_SETTING_EVENT, update);
        window.removeEventListener(FLOW_SETTING_EVENT, update);
      });
    },
    { strategy: "document-ready" },
  );

  const toggle = $(async (setting: Setting) => {
    if (!state.ready || state.saving) return;
    const previous = state[setting];
    state[setting] = !previous;
    state.saving = true;
    state.error = "";
    try {
      const { key, event } = SETTINGS[setting];
      const next = state[setting];
      await saveMetaToIdb(key, next);
      if ((await loadMetaFromIdb<boolean>(key)) !== next) {
        throw new Error("Setting was not saved");
      }
      window.dispatchEvent(new CustomEvent(event));
    } catch {
      state[setting] = previous;
      state.error = "Could not save this setting. Try again.";
    } finally {
      state.saving = false;
    }
  });

  return (
    <section class="review-controls" aria-label="Review settings">
