import { chromium, expect } from '@playwright/test';
import { mkdir, writeFile } from 'node:fs/promises';

const directory = new URL('./', import.meta.url).pathname;
await mkdir(directory, { recursive: true });
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ viewport: { width: 1440, height: 960 } });
await context.route('**/*', route => {
  const url = new URL(route.request().url());
  return url.hostname === '127.0.0.1' || url.hostname === 'localhost' || url.protocol === 'data:'
    ? route.continue() : route.abort();
});
const page = await context.newPage();
await page.route('**/__manual-desk-seed', route => route.fulfill({ contentType: 'text/html', body: '<!doctype html><title>Sample draft</title>' }));
await page.goto('http://127.0.0.1:5180/__manual-desk-seed');
await page.evaluate(async () => {
  const idb = await import('/src/utils/idb.ts');
  const uc = await import('/src/utils/user-comments.ts');
  const house = await import('/src/utils/house-store.ts');
  const now = Date.now();
  const id = 'manual-salt-roads';
  await idb.saveFoliosToIdb([
    { id, name: 'Salt Roads', type: 'draft', createdAt: now, updatedAt: now },
    { id: 'manual-coast', name: 'The Coast in Winter', type: 'draft', createdAt: now, updatedAt: now },
  ]);
  await idb.saveActiveFolioIdToIdb(id);
  const html = '<h1>Salt Roads</h1>' +
    '<p>The salt caravans left before dawn. In the blue light, the coast looked less like a boundary than a promise of somewhere else.</p>' +
    '<p>The traders <span data-persona-note-id="manual-note" data-persona-note-author="Marguerite" data-persona-note-color="#b0413e" data-persona-note-label="Pacing" data-persona-note-note="Let this gesture carry the scene. The next sentence can tell us what was at stake." data-persona-note-quote="weighed their loads by the handful">weighed their loads by the handful</span> and argued about the weather. Each bag had to last until the next town.</p>' +
    '<p>At the ford, <span data-suggestion-id="manual-suggestion" data-suggestion-author="Marguerite" data-suggestion-color="#b0413e" data-suggestion-replacement="the mules refused the water" data-suggestion-rationale="Show the obstacle through something the reader can see." data-suggestion-versionId="manual-version">progress slowed considerably</span>. The youngest trader went ahead to find a shallower crossing.</p>' +
    '<p>By the fourth day, <span class="twyne-comment-mark" data-comment-id="manual-comment" data-comment-author="You">the road forgot the sea entirely</span> and turned inland. A white crust remained on the straps long after the wind lost its salt.</p>' +
    '<p>They carried a small piece of the coast with them: not the water, but the work it had made possible.</p>';
  await idb.saveFolioContentToIdb(id, html);
  await idb.saveBriefToIdb(id, { answers: { workingTitle: 'Salt Roads', format: 'Travel essay', audience: '', goal: '', tone: 'Patient, sensory, and precise.', constraints: '', successSignal: 'The reader can picture the journey.' }, attachments: [], completedAt: now, updatedAt: now });
  await uc.saveUserComments([{ id: 'manual-comment', folioId: id, text: 'Check the route against the map before calling it inland.', author: 'You', anchor: 'the road forgot the sea entirely', resolved: false, createdAt: now, updatedAt: now, replies: [] }]);
  await idb.saveMetaToIdb('signin-toast-dismissed', true);
  await idb.saveMetaToIdb('live-review-enabled', false);
  await idb.saveMetaToIdb('flow-reading-enabled', true);
  await idb.saveMetaToIdb('cover-lookups-enabled', false);
  await house.setHouseName('Éditions du Passage');
  await house.setHouseField('goal', 'Make familiar places strange again.');
  await house.setHouseField('audience', 'Readers who travel through stories.');
  await house.setHouseField('tone', 'Attentive, concrete, generous.');
  const state = await house.createCollection('Journeys & Returns', [id]);
  await house.updateCollection(state.collections[0].id, { description: 'Essays on roads, memory, and finding a way home.', field: { name: 'tone', value: 'A close eye for landscape; a quiet sense of wonder.' } });
  await house.upsertCharterItem({ scope: 'house', ownerRef: 'house', text: 'Ground every claim in a concrete scene.', severity: 'must', kind: 'style' });
});
await page.goto('http://127.0.0.1:5180/editor/?e2e=1');
await expect(page.locator('.ProseMirror').first()).toBeVisible({ timeout: 30000 });
await page.waitForTimeout(2500);
await page.screenshot({ path: `${directory}/probe-editor.png` });
console.log(await page.locator('body').innerText());
console.log(JSON.stringify(await page.locator('button').evaluateAll(els => els.map(el => ({ text: el.innerText, title: el.title, aria: el.getAttribute('aria-label') }))), null, 2));
await context.close();
await browser.close();

