    width: 20px;
    background: yellow;
    border-radius: 100%;
    height: 20px;
    padding: 3px;
    pointer-events: all;
    cursor: pointer;
  }

  #icon svg {
    width: 100%;
    height: auto;
    pointer-events: none;
  }

  dialog {
    padding: 0;
    border: 0;
    margin: 0 5px;
    background: #ffffe8;
    color: black;
    width: 250px;
    font-size: 11px;
    position: absolute;
    inset-inline-start: unset;
    inset-inline-end: unset;
    border-radius: 5px;
    pointer-events: all;
    overflow: hidden;
    box-shadow: 0px -2px 20px 0px #0000002e;
    z-index: 10000;
  }

  .top {
    bottom: calc(100% + 5px);
  }
  .bottom {
    top: 40px;
  }
  .right {
    inset-inline-start: 0;
    inset-inline-end: unset;
  }
  .left {
    inset-inline-start: unset;
    inset-inline-end: calc(100% - 40px);
  }

  .content {
    padding: 5px;
  }

  #loc {
    background: #2e3801;
    color: #d2d2d2;
    font-family: monospace;
    padding: 3px 5px;
    pointer-events: all;
    margin: 0;
    border: 0;
    cursor: pointer;
    font-size: 11px;
    width: calc(100% - 24px);
    text-overflow: ellipsis;
    overflow: hidden;
    display: block;
    direction: rtl;
    text-align: right;
  }
  #loc:hover {
    background: #3a4a01;
  }

  pre {
    background: #f1fb8e;
    padding: 5px;
    margin: 5px 0;
    border-radius: 3px;
    user-select: none;
  }

  pre span {
    user-select: all;
  }

  a {
    text-decoration: underline;
  }

  #close {
    border: 0;
    width: 25px;
    height: 25px;
    position: absolute;
    right: 0;
    top: 0;
    background: #ffe14f;
    color: black;
    font-weight: 900;
    padding: 0;
    margin: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    cursor: pointer;
  }
  #close:hover {
